svg.script:
(function(){
 const svg=document.documentElement, NS='http://www.w3.org/2000/svg';
 const meta=JSON.parse(document.getElementById('pbn-meta').textContent);
 const regions=[...svg.querySelectorAll('.region')], labels=document.getElementById('number-labels'), legend=document.getElementById('legend');
 let numbersVisible=true;
 const make=(tag,a,t)=>{const e=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(a||{}))e.setAttribute(k,v);if(t!=null)e.textContent=t;return e};
 function nodes(el){return el.dataset.paintChildren==='1'?[el,...el.querySelectorAll('path,rect,circle,ellipse,polygon,polyline')]:[el]}
 function apply(el,on){const c=el.dataset.suggested,mode=el.dataset.paintMode||'fill';el.dataset.painted=on?'1':'0';nodes(el).forEach(n=>{if(mode==='stroke'){n.style.fill='none';n.style.stroke=on?c:'#a59d91'}else n.style.fill=on?c:'#fffdf8'});const l=labels.querySelector('[data-label-for="'+el.id+'"]');if(l)l.style.display=on?'none':(numbersVisible?'inline':'none')}
 regions.forEach((el,i)=>{if(!el.id)el.id='region-'+String(i+1).padStart(3,'0');const n=+el.dataset.color;el.dataset.suggested=el.dataset.suggested||meta.palette[n-1]?.hex||'#ddd';apply(el,false);try{const b=el.getBBox(),area=b.width*b.height;if(b.width>22&&b.height>18&&area>520){const fs=Math.max(9,Math.min(22,Math.sqrt(area)/7.5));labels.appendChild(make('text',{x:(b.x+b.width/2).toFixed(1),y:(b.y+b.height/2+fs*.35).toFixed(1),'text-anchor':'middle','font-size':fs.toFixed(1),class:'pbn-number','data-label-for':el.id},String(n)))}}catch(_){ }
  const run=e=>{if(e.shiftKey)regions.filter(r=>r.dataset.color===el.dataset.color).forEach(r=>apply(r,true));else apply(el,true)};el.addEventListener('click',run);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run(e)}})
 });
 const cols=4,startX=34,startY=940,cellW=208,cellH=39,rows=Math.ceil(meta.palette.length/cols),buttonY=startY+rows*cellH+14,legendH=buttonY-900+58;
 svg.setAttribute('viewBox',`0 0 900 ${900+legendH+15}`);svg.setAttribute('height',String(900+legendH+15));legend.setAttribute('display','inline');document.getElementById('legend-bg').setAttribute('height',String(legendH));
 meta.palette.forEach((p,i)=>{const x=startX+(i%cols)*cellW,y=startY+Math.floor(i/cols)*cellH,g=make('g',{class:'control',tabindex:'0',role:'button','aria-label':'Paint all color '+(i+1)});g.appendChild(make('rect',{x,y,width:34,height:27,rx:5,fill:p.hex,class:'legend-swatch'}));g.appendChild(make('text',{x:x+43,y:y+19,'font-size':14,'font-weight':700,class:'legend-label'},`${i+1}. ${p.name}`));const run=()=>regions.filter(r=>+r.dataset.color===i+1).forEach(r=>apply(r,true));g.addEventListener('click',run);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}});legend.appendChild(g)});
 const button=(x,label,fn)=>{const g=make('g',{class:'control',tabindex:0,role:'button','aria-label':label});g.appendChild(make('rect',{x,y:buttonY,width:164,height:38,rx:12,fill:'#fff9ed',stroke:'#6f5a43','stroke-width':2}));g.appendChild(make('text',{x:x+82,y:buttonY+25,'text-anchor':'middle','font-size':16,'font-weight':800,class:'legend-label'},label));g.addEventListener('click',fn);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}});legend.appendChild(g)};
 button(150,'Fill all',()=>regions.forEach(r=>apply(r,true)));button(368,'Reset',()=>regions.forEach(r=>apply(r,false)));button(586,'Toggle numbers',()=>{numbersVisible=!numbersVisible;labels.style.display=numbersVisible?'inline':'none'});
})();
